import { useEffect, useRef } from 'react';

/**
 * Animated "noise gradient" background — a full-screen WebGL2 fragment shader
 * sampling 3D Perlin noise (3rd axis = time, so the field slowly drifts) and
 * blending soft colored blobs. Generated by the `noise-gradient` skill and
 * embedded inline (skill embedding option 2) so it can react to the pointer.
 *
 * The field eases very gently toward the cursor (`parallax`), smoothed each
 * frame so motion feels calm rather than jumpy.
 *
 * Renders a fixed, click-through `<canvas>` behind page content. Degrades
 * gracefully: if WebGL2 is unavailable or fails (jsdom, ancient browsers, a
 * lost context) it paints a solid fallback of the first color — it never
 * throws out of the effect, so it can't crash the React tree.
 */

// --- Shader source (verbatim from the noise-gradient skill template) --------
const VERT = `#version 300 es
in vec2 aPos;
out vec2 vUv;
void main(){
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 fragColor;

uniform float uTime, uSpeed, uNoiseDensity, uNoiseStrength, uBrightness, uAlpha;
uniform vec3  uColor1, uColor2, uColor3;
uniform vec2  uAspectRatio, uOffset;

// --- Classic 3D Perlin noise (Stefan Gustavson, webgl-noise) ---------------
vec3 mod289(vec3 x){ return x - floor(x * (1.0/289.0)) * 289.0; }
vec4 mod289(vec4 x){ return x - floor(x * (1.0/289.0)) * 289.0; }
vec4 permute(vec4 x){ return mod289(((x*34.0)+1.0)*x); }
vec4 taylorInvSqrt(vec4 r){ return 1.79284291400159 - 0.85373472095314 * r; }
vec3 fade(vec3 t){ return t*t*t*(t*(t*6.0-15.0)+10.0); }

float cnoise(vec3 P){
  vec3 Pi0 = floor(P);
  vec3 Pi1 = Pi0 + vec3(1.0);
  Pi0 = mod289(Pi0);
  Pi1 = mod289(Pi1);
  vec3 Pf0 = fract(P);
  vec3 Pf1 = Pf0 - vec3(1.0);
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = Pi0.zzzz;
  vec4 iz1 = Pi1.zzzz;

  vec4 ixy = permute(permute(ix) + iy);
  vec4 ixy0 = permute(ixy + iz0);
  vec4 ixy1 = permute(ixy + iz1);

  vec4 gx0 = ixy0 * (1.0/7.0);
  vec4 gy0 = fract(floor(gx0) * (1.0/7.0)) - 0.5;
  gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
  vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0 * (step(0.0, gx0) - 0.5);
  gy0 -= sz0 * (step(0.0, gy0) - 0.5);

  vec4 gx1 = ixy1 * (1.0/7.0);
  vec4 gy1 = fract(floor(gx1) * (1.0/7.0)) - 0.5;
  gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
  vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1 * (step(0.0, gx1) - 0.5);
  gy1 -= sz1 * (step(0.0, gy1) - 0.5);

  vec3 g000 = vec3(gx0.x, gy0.x, gz0.x);
  vec3 g100 = vec3(gx0.y, gy0.y, gz0.y);
  vec3 g010 = vec3(gx0.z, gy0.z, gz0.z);
  vec3 g110 = vec3(gx0.w, gy0.w, gz0.w);
  vec3 g001 = vec3(gx1.x, gy1.x, gz1.x);
  vec3 g101 = vec3(gx1.y, gy1.y, gz1.y);
  vec3 g011 = vec3(gx1.z, gy1.z, gz1.z);
  vec3 g111 = vec3(gx1.w, gy1.w, gz1.w);

  vec4 norm0 = taylorInvSqrt(vec4(dot(g000,g000), dot(g010,g010), dot(g100,g100), dot(g110,g110)));
  g000 *= norm0.x; g010 *= norm0.y; g100 *= norm0.z; g110 *= norm0.w;
  vec4 norm1 = taylorInvSqrt(vec4(dot(g001,g001), dot(g011,g011), dot(g101,g101), dot(g111,g111)));
  g001 *= norm1.x; g011 *= norm1.y; g101 *= norm1.z; g111 *= norm1.w;

  float n000 = dot(g000, Pf0);
  float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
  float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
  float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
  float n111 = dot(g111, Pf1);

  vec3 fade_xyz = fade(Pf0);
  vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
  vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
  float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x);
  return 2.2 * n_xyz;
}

void main(){
  vec2 uv = vUv;
  uv -= vec2(0.5);
  uv *= uAspectRatio;     // keep blobs circular regardless of canvas shape
  uv += vec2(0.5);

  uv = uv * 5.0 - 2.5;
  uv += uOffset;
  float t = uTime * uSpeed;

  float distortion = 0.75 * cnoise(0.43 * vec3(uv, 0.0) * uNoiseDensity + t);

  vec3 color = mix(uColor1, uColor2, smoothstep(-3.0, 3.0, uv.x));
  color = mix(color, uColor3, distortion * uNoiseStrength);

  color *= uBrightness;
  color *= 0.8;

  fragColor = vec4(color, uAlpha);
}`;

function hex2rgb(h) {
  const n = parseInt(h.replace('#', ''), 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

export default function NoiseGradient({
  colors = ['#FFFFFF', '#99F6E4', '#2DD4BF'],
  blobSize = 1.5,
  speed = 0.08,
  brightness = 1.25,
  noiseStrength = 1.0,
  alpha = 1.0,
  renderScale = 1.0,
  // How far the field eases toward the cursor, in shader units (uv spans 5).
  // Kept small for a "very light" reaction. 0 disables pointer parallax.
  parallax = 0.22,
  // Per-frame easing toward the pointer target (lower = slower/softer).
  ease = 0.04,
  className,
  style,
}) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    let gl = null;
    try {
      gl = canvas.getContext('webgl2', { antialias: false, alpha: true });
    } catch {
      gl = null;
    }
    if (!gl) {
      // WebGL2 unavailable (jsdom / very old browsers): solid fallback.
      canvas.style.background = colors[0];
      return undefined;
    }

    let raf = null;
    let removeListeners = () => {};
    const stop = () => {
      if (raf) { cancelAnimationFrame(raf); raf = null; }
      removeListeners();
    };

    try {
      const compile = (type, src) => {
        const s = gl.createShader(type);
        gl.shaderSource(s, src);
        gl.compileShader(s);
        if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
          throw new Error(gl.getShaderInfoLog(s) || 'shader compile failed');
        }
        return s;
      };

      const prog = gl.createProgram();
      gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
      gl.linkProgram(prog);
      if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
        throw new Error(gl.getProgramInfoLog(prog) || 'program link failed');
      }
      gl.useProgram(prog);

      // Full-screen triangle
      const vao = gl.createVertexArray();
      gl.bindVertexArray(vao);
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      const aPos = gl.getAttribLocation(prog, 'aPos');
      gl.enableVertexAttribArray(aPos);
      gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

      const U = {};
      ['uTime', 'uSpeed', 'uNoiseDensity', 'uNoiseStrength', 'uBrightness', 'uAlpha',
        'uColor1', 'uColor2', 'uColor3', 'uAspectRatio', 'uOffset']
        .forEach((n) => { U[n] = gl.getUniformLocation(prog, n); });

      const cols = colors.slice();
      while (cols.length < 3) cols.push(cols[cols.length - 1]);

      const setStaticUniforms = () => {
        gl.uniform1f(U.uSpeed, speed);
        gl.uniform1f(U.uNoiseDensity, 1.0 / blobSize);
        gl.uniform1f(U.uNoiseStrength, noiseStrength);
        gl.uniform1f(U.uBrightness, brightness);
        gl.uniform1f(U.uAlpha, alpha);
        gl.uniform3fv(U.uColor1, hex2rgb(cols[0]));
        gl.uniform3fv(U.uColor2, hex2rgb(cols[1]));
        gl.uniform3fv(U.uColor3, hex2rgb(cols[2]));
      };

      const resize = () => {
        const w = Math.max(1, Math.round(canvas.clientWidth * renderScale));
        const h = Math.max(1, Math.round(canvas.clientHeight * renderScale));
        if (canvas.width !== w || canvas.height !== h) {
          canvas.width = w;
          canvas.height = h;
          gl.viewport(0, 0, w, h);
        }
        const aspect = w / h;
        if (aspect >= 1) gl.uniform2f(U.uAspectRatio, aspect, 1.0);
        else gl.uniform2f(U.uAspectRatio, 1.0, 1.0 / aspect);
      };

      // Gentle pointer parallax: track a target offset, ease the live offset to it.
      const reduceMotion = typeof window !== 'undefined' && typeof window.matchMedia === 'function'
        ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
        : false;
      const target = { x: 0, y: 0 };
      const cur = { x: 0, y: 0 };
      let startT = null;

      const draw = (tSeconds) => {
        resize();
        setStaticUniforms();
        cur.x += (target.x - cur.x) * ease;
        cur.y += (target.y - cur.y) * ease;
        gl.uniform2f(U.uOffset, cur.x, cur.y);
        gl.uniform1f(U.uTime, tSeconds);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
      };

      const loop = (now) => {
        if (startT === null) startT = now;
        draw((now - startT) / 1000);
        raf = requestAnimationFrame(loop);
      };

      const onPointerMove = (e) => {
        const nx = e.clientX / window.innerWidth - 0.5;   // -0.5 … 0.5
        const ny = e.clientY / window.innerHeight - 0.5;
        target.x = nx * parallax;
        target.y = -ny * parallax;                        // screen y is top-down
      };
      const onResize = () => { if (!raf) draw(startT === null ? 7.3 : 0); };

      const pointerActive = !reduceMotion && parallax > 0;
      if (pointerActive) window.addEventListener('pointermove', onPointerMove, { passive: true });
      window.addEventListener('resize', onResize);
      removeListeners = () => {
        if (pointerActive) window.removeEventListener('pointermove', onPointerMove);
        window.removeEventListener('resize', onResize);
      };

      if (reduceMotion) {
        // Honor reduced-motion: paint one calm static frame, no animation loop.
        draw(7.3);
      } else {
        raf = requestAnimationFrame(loop);
      }
    } catch {
      // Any WebGL failure (e.g. a context lost during a StrictMode remount):
      // tear down whatever we started and fall back to a solid color.
      stop();
      canvas.style.background = colors[0];
      return undefined;
    }

    return stop;
  }, [colors, blobSize, speed, brightness, noiseStrength, alpha, renderScale, parallax, ease]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className={className}
      style={{ pointerEvents: 'none', ...style }}
    />
  );
}
